"""Edge-case tests for figure-api (Round 2) — generated by bug-hunter agent.

Round 1 found 4 bugs (catplot/box integer column crash x3, CSS shorthand hex
rejection x1). Those are covered by the existing tests. This round targets:

- configure() with format presets, domain clamping, tick_values
- relplot with style/size parameters
- catplot with order/hue_order, orient="h" for non-box kinds
- displot multiple="fill"/"dodge"
- lmplot with various methods and hue
- regplot, residplot edge cases
- configure_grid band_colors, configure_padding auto=False
- Multiple configure calls of same domain (last-wins)
- configure_axis x=False (y-only config)
- configure with axis_y2
- labs() unknown key error
- Annotations rendered in SVG output
- catplot seed parameter
- NaN in hue columns across figure functions
- configure on HConcat/VConcat composed charts
- mark_line(point=True) composition
- All-null column in figure functions
- configure_axis domain_min/domain_max on rendered SVG
- Extreme tick_values
- configure_color domain+range interaction
- override + configure interaction on rendered SVG
"""

from __future__ import annotations

import json
import math

import polars as pl
import pytest

import ferrum as fm
from ferrum.configure import (
    AxisConfig,
    ColorConfig,
    Configure,
    GridConfig,
    LegendConfig,
    PaddingConfig,
    TitleConfig,
)
from ferrum.structural import BreakAxis, Inset, SecondaryY
import ferrum.annotation as ann
from ferrum.annotation import Annotate


