# ===================================================================
# Category: configure_axis with format presets
# ===================================================================


class TestConfigureAxisFormatPresets:
    """Tests for AxisConfig.label_format preset resolution and rendering.
    Targets configure.py lines 109-131 and format_presets.py resolve_format.
    """

    def test_axis_config_percent_preset_resolves(self):
        """AxisConfig.to_dict should resolve 'percent' to '.1%'."""
        cfg = AxisConfig(label_format="percent")
        d = cfg.to_dict()
        assert d["label_format"] == ".1%"

    def test_axis_config_currency_preset_resolves(self):
        """AxisConfig.to_dict should resolve 'currency' to '$,.0f'."""
        cfg = AxisConfig(label_format="currency")
        d = cfg.to_dict()
        assert d["label_format"] == "$,.0f"

    def test_axis_config_ordinal_preset_resolves(self):
        """AxisConfig.to_dict should resolve 'ordinal' to '__ordinal__' sentinel."""
        cfg = AxisConfig(label_format="ordinal")
        d = cfg.to_dict()
        assert d["label_format"] == "__ordinal__"

    def test_configure_axis_format_preset_renders_svg(self, simple_df):
        """Chart with configure_axis(label_format='percent') should render valid SVG.
        Exercises the full pipeline: AxisConfig -> _resolve_chart_config -> Rust renderer.
        """
        chart = (
            fm.Chart(simple_df)
            .mark_bar()
            .encode(x="x", y="y")
            .configure_axis(label_format="percent")
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_configure_axis_format_raw_renders_svg(self, simple_df):
        """Chart with configure_axis(label_format_raw='.3f') should render valid SVG."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_format_raw=".3f")
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg


