# ===================================================================
# Category: catplot order and hue_order
# ===================================================================


class TestCatplotOrderHueOrder:
    """Tests for catplot order/hue_order wiring.
    Targets distribution.py catplot lines 529-534.
    """

    def test_catplot_order_sets_sort_on_x(self, cat_float_df):
        """catplot(order=[...]) should set sort on the x encoding.
        distribution.py line 530: enc['x'] = _X(cat_field, sort=list(order))."""
        chart = fm.catplot(cat_float_df, x="group", y="value", kind="strip", order=["b", "a"])
        x_enc = chart._encoding.get("x")
        assert x_enc is not None
        assert hasattr(x_enc, "_kwargs")
        assert x_enc._kwargs.get("sort") == ["b", "a"]

    def test_catplot_hue_order_sets_sort_on_color(self):
        """catplot(hue_order=[...]) should set sort on the color encoding.
        distribution.py line 533: enc['color'] = _Color(hue, sort=list(hue_order))."""
        df = pl.DataFrame(
            {
                "cat": ["a"] * 10 + ["b"] * 10,
                "val": [float(x) for x in range(20)],
                "grp": (["X", "Y"] * 10),
            }
        )
        chart = fm.catplot(df, x="cat", y="val", hue="grp", kind="strip", hue_order=["Y", "X"])
        color_enc = chart._encoding.get("color")
        assert color_enc is not None
        assert hasattr(color_enc, "_kwargs")
        assert color_enc._kwargs.get("sort") == ["Y", "X"]

    def test_catplot_order_renders_svg(self, cat_float_df):
        """catplot with explicit order should produce valid SVG."""
        chart = fm.catplot(cat_float_df, x="group", y="value", kind="strip", order=["b", "a"])
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg


