        """lmplot(method='loess') should render valid SVG.
        regression.py lines 600-609: mark_smooth(method='loess')."""
        chart = fm.lmplot(simple_df, x="x", y="y", method="loess", ci=None, show_metrics=False)
        svg = chart.to_svg()
