# ===================================================================
# Category: Multiple configure calls of same domain (last-wins)
# ===================================================================


class TestConfigureSameDomainLastWins:
    """Tests that multiple configure calls for the same domain merge correctly,
    with later values overriding earlier ones.
    Targets _resolve_chart_config merge logic in _render.py.
    """

    def test_two_configure_axis_last_wins(self, simple_df):
        """Two configure_axis calls: later label_angle should override earlier."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_axis(label_angle=-45, tick_count=5)
            .configure_axis(label_angle=-90)
        )
        config = chart._resolve_chart_config()
        # Second call set label_angle=-90, should override -45
        assert config.get("axis", {}).get("label_angle") == -90

    def test_two_configure_legend_last_wins(self, simple_df):
        """Two configure_legend calls: later orient should override earlier."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_legend(orient="bottom")
            .configure_legend(orient="top")
        )
        config = chart._resolve_chart_config()
        assert config.get("legend", {}).get("orient") == "top"

    def test_two_configure_title_last_wins(self, simple_df):
        """Two configure_title calls: later font_size should override earlier."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_title(font_size=14)
            .configure_title(font_size=24)
        )
        config = chart._resolve_chart_config()
        assert config.get("title", {}).get("font_size") == 24

    def test_configure_grid_override_color(self, simple_df):
        """Two configure_grid calls: later color should override earlier."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure_grid(color="#ccc")
            .configure_grid(color="#eee")
        )
        config = chart._resolve_chart_config()
        assert config.get("grid", {}).get("color") == "#eee"


