class TestConfigureAxisY2:
    """Tests for Configure(axis_y2=...) wiring.
    Targets chart.py configure() line 4710 and configure.py Configure dataclass.
    """

    def test_configure_axis_y2_in_config_dict(self, simple_df):
        """Configure(axis_y2=AxisConfig(...)) should appear in resolved config."""
        chart = (
            fm.Chart(simple_df)
            .mark_point()
            .encode(x="x", y="y")
            .configure(axis_y2=AxisConfig(label_angle=45, label_color="red"))
        )
        config = chart._resolve_chart_config()
        assert "axis_y2" in config
        assert config["axis_y2"]["label_angle"] == 45
