class TestAxisMethod:
    """Tests for Chart.axis() method.
    Targets chart.py axis() lines 4370-4430.
    """

    def test_axis_show_false_hides_both(self, simple_df):
        """axis(show=False) should hide both axes.
        chart.py axis line 4422-4423."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y").axis(show=False)
        assert chart._axis_x is False
        assert chart._axis_y is False

    def test_axis_show_and_x_raises(self, simple_df):
        """axis(show=..., x=...) should raise ValueError.
        chart.py axis line 4419-4420."""
        with pytest.raises(ValueError, match="show"):
            fm.Chart(simple_df).mark_point().encode(x="x", y="y").axis(show=False, x=True)

    def test_axis_x_false_y_true(self, simple_df):
        """axis(x=False, y=True) should hide x and show y."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y").axis(x=False, y=True)
        assert chart._axis_x is False
        assert chart._axis_y is True

    def test_axis_false_renders_svg(self, simple_df):
        """Chart with axis(show=False) should still render valid SVG."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y").axis(show=False)
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg


