class TestToDictCompleteness:
    """Tests that to_dict/to_json capture all spec components."""

    def test_to_dict_includes_facet(self, iris_df):
        """to_dict should include facet when facet() was called."""
        chart = (
            fm.Chart(iris_df)
            .mark_point()
            .encode(x="sepal_length", y="sepal_width")
            .facet("species")
        )
        d = chart.to_dict()
        assert "facet" in d

    def test_to_json_pretty_print(self, simple_df):
        """to_json(indent=2) should produce indented JSON."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y")
        j = chart.to_json(indent=2)
        assert "\n" in j
        # Should be valid JSON
        parsed = json.loads(j)
        assert parsed["mark"] == "point"

    def test_to_dict_captures_layers(self, simple_df):
        """to_dict for a layered chart should include layers array."""
        chart = fm.Chart(simple_df).mark_point().encode(x="x", y="y") + fm.Chart(
            simple_df
        ).mark_line().encode(x="x", y="y")
        d = chart.to_dict()
        assert "layers" in d
        assert len(d["layers"]) >= 2


