# Category: facet validation
# ===================================================================


class TestFacetValidation:
    """Tests for facet() method validation.
    Targets chart.py facet() lines 4305-4336.
    """

    def test_facet_no_args_raises(self, simple_df):
        """facet() with no arguments should raise ValueError.
        chart.py facet line 4335-4336."""
        with pytest.raises(ValueError, match="facet"):
            fm.Chart(simple_df).mark_point().encode(x="x", y="y").facet()

    def test_facet_field_string(self, iris_df):
        """facet(field='species') should set wrap mode."""
        chart = (
            fm.Chart(iris_df)
            .mark_point()
            .encode(x="sepal_length", y="sepal_width")
            .facet("species")
        )
        assert chart._facet is not None
        assert chart._facet.mode_kind == "wrap"
        assert chart._facet.field == "species"

    def test_facet_grid_mode(self):
        """facet(row=..., col=...) should set grid mode."""
        df = pl.DataFrame(
            {
                "x": [1.0, 2.0, 3.0, 4.0],
                "y": [1.0, 2.0, 3.0, 4.0],
                "r": ["R1", "R1", "R2", "R2"],
                "c": ["C1", "C2", "C1", "C2"],
            }
        )
        chart = fm.Chart(df).mark_point().encode(x="x", y="y").facet(row="r", col="c")
        assert chart._facet is not None
        assert chart._facet.mode_kind == "grid"
        assert chart._facet.row == "r"
        assert chart._facet.col == "c"
